import json
import os
import pickle

def load_user_configs(config_dir):
    """Load and apply user configuration files from directory."""
    settings = {}

    for filename in os.listdir(config_dir):
        if filename.endswith('.json'):
            filepath = os.path.join(config_dir, filename)

            # Load the serialized config object
            with open(filepath, 'rb') as f:
                user_config = pickle.load(f)  # Deserialize pickle data

            username = user_config.get('username')
            settings[username] = user_config

    return settings

def apply_settings(settings):
    """Apply loaded settings to dashboard."""
    for username, config in settings.items():
        # Apply each user's config
        update_dashboard(username, config)

def update_dashboard(username, config):
    print(f"Applying settings for {username}: {config}")

if __name__ == '__main__':
    configs = load_user_configs('./user_configs')
    apply_settings(configs)
